from robot.utils.robottime import timestr_to_secs

from .base import BaseInterface
from ..util import wrap_result
from ..validators import IsString
from ..converter import to_bool


class SoftwareUpdateInterface(BaseInterface):

    def update_software(self, sw_package, should_activate=True, timeout=600, alias="default"):
        """Perform software update.

        :param string sw_package: Path to software package.
        :param boolean should_activate: Activate software flag.
        :param float timeout: Time to wait for positive procedure result.
        :param string alias: Name of execution context.
        """
        timeout = timestr_to_secs(timeout)
        should_activate = to_bool(should_activate)

        self.store.get(alias).execute_procedure(
            "softwareUpdate", {"shouldActivate": should_activate}, timeout, input_file_name=sw_package)

    def download_and_update_software(self, url, target_bd, should_activate=True, timeout=600, alias="default"):
        """Download software package and perform update.

        :param string url: File server URL.
        :param string target_bd: Remote path to software package.
        :param boolean should_activate: Activate software flag.
        :param float timeout: Time to wait for positive procedure result.
        :param string alias: Name of execution context.
        """
        IsString().check(url)
        IsString().check(target_bd)

        should_activate = to_bool(should_activate)
        timeout = timestr_to_secs(timeout)

        self.store.get(alias).execute_procedure(
            "softwareUpdate", {"fileServerUrl": url, "targetBd": target_bd, "shouldActivate": should_activate}, timeout)

    def rollback_software(self, timeout=300, alias="default"):
        """Perform software rollback.

        :param float timeout: Time to wait for positive procedure result.
        :param string alias: Name of execution context.

        :rtype: string
        :return: software rollback status
        """
        timeout = timestr_to_secs(timeout)
        return self.store.get(alias).execute_procedure("swRollback", {}, timeout)

    def abort_software_update(self, timeout=60, alias="default"):
        """Abort software update.

        :param float timeout: Time to wait for positive procedure result.
        :param string alias: Name of execution context.
        """
        timeout = timestr_to_secs(timeout)
        self.store.get(alias).execute_procedure("swDownloadAbort", {}, timeout)

    def get_sw_update_report(self, target_file_name, timeout=120, alias="default"):
        """ Get SWDLreport.txt file from BTS

        :param target_file_name: File name for SWDLreport.txt content to be saved.
        :param timeout: Time to wait for positive procedure result.
        :param alias: Name of execution context.
        """
        timeout = timestr_to_secs(timeout)
        IsString().check(target_file_name)

        self.store.get(alias).execute_procedure("swUpdateReport", {}, timeout, output_file_name=target_file_name)

    @wrap_result
    def get_software_info(self, timeout=10, alias="default"):
        """Get software info.

        :param float timeout: Time to wait for positive procedure result.
        :param string alias: Name of execution context.

        :rtype: list
        :return: list of active software.
        """
        timeout = timestr_to_secs(timeout)
        return self.store.get(alias).execute_infomodel_request("swInfo", {"dataType": "swView"}, timeout)

    def save_sw_history_report(self, target_file_name, timeout=120, alias="default"):
        """ Saves SW history report

        :param target_file_name: File name for SW history report content to be saved.
        :param timeout: Time to wait for positive procedure result.
        :param alias: Name of execution context.
        """
        timeout = timestr_to_secs(timeout)
        IsString().check(target_file_name)

        self.store.get(alias).execute_procedure("swHistoryReport", {}, timeout, output_file_name=target_file_name)

    def software_precheck_local(self, sw_package, precheck_type, timeout=120, alias="default"):
        """ Software precheck for local file

        :param string sw_package: Path to software package.
        :param string precheck_type: precheck type.
                                     More info at: https://onion.wroclaw.nsn-rdnet.net/branches/master/cli-docs/tutorial-softwarePrecheck.html
        :param timeout: Time to wait for positive procedure result.
        :param alias: Name of execution context.

        :rtype: string
        :return: software postcheck status
        """
        timeout = timestr_to_secs(timeout)
        IsString().check(precheck_type)

        return self.store.get(alias).execute_procedure("softwarePrecheck", {"precheckType": precheck_type}, timeout, input_file_name=sw_package)

    def software_precheck_remote(self, file_server_url, target_bd, precheck_type, timeout=120, alias="default"):
        """ Software precheck for remote server

        :param string file_server_url: server url.
        :param string target_bd: targetBd file name.
        :param string precheck_type: precheck type.
                                     More info at: https://onion.wroclaw.nsn-rdnet.net/branches/master/cli-docs/tutorial-softwarePrecheck.html
        :param timeout: Time to wait for positive procedure result.
        :param alias: Name of execution context.

        :rtype: string
        :return: software postcheck status
        """
        timeout = timestr_to_secs(timeout)
        IsString().check(file_server_url)
        IsString().check(target_bd)
        IsString().check(precheck_type)

        return self.store.get(alias).execute_procedure("softwarePrecheck",
                                                       {"fileServerUrl": file_server_url, "targetBd": target_bd, "precheckType": precheck_type},
                                                       timeout)

    def software_postcheck(self, timeout=120, alias="default"):
        """ Software postcheck

        :param timeout: Time to wait for positive procedure result.
        :param alias: Name of execution context.

        :rtype: string
        :return: software postcheck status
        """
        timeout = timestr_to_secs(timeout)

        return self.store.get(alias).execute_procedure("softwarePostcheck", {}, timeout)
